import React,{forwardRef,useEffect,useImperativeHandle,useMemo,useRef,useState} from 'react';
import {AccessibilityInfo,PanResponder,View} from 'react-native';
import {Canvas,Circle,Line,Path,Rect} from '@shopify/react-native-skia';
import {createEditor,gesture,pathValue,setMode,splitSegment,tick,undo,zoom,type Anchor,type PathValue} from './pathMath';
import {palette as c,pathScene} from './pathScene';
export type MotionPathHandle={split:()=>void;mode:(v:'smooth'|'corner')=>void;undo:()=>void;reset:()=>void;zoom:(factor:number)=>void;play:()=>void;select:(index:number)=>void;value:()=>PathValue};
export type MotionPathProps={initialAnchors?:Anchor[];slowMotion?:boolean;reducedMotion?:boolean;onChange?:(value:PathValue)=>void;onChangeEnd?:(value:PathValue)=>void;onStatus?:(value:{selected:number;count:number;mode:string;playing:boolean;zoom:number;length:number})=>void};
/** Open cubic path editor. Coordinates are logical 340×320 canvas units. No SVG parser required. */
export const MotionPathEditor=forwardRef<MotionPathHandle,MotionPathProps>(function MotionPathEditor({initialAnchors,slowMotion=false,reducedMotion,onChange,onChangeEnd,onStatus},ref){
 const model=useRef(createEditor(initialAnchors)),g=useMemo(()=>gesture(model.current),[]),[scene,setScene]=useState(()=>pathScene(model.current)),[systemReduce,setSystemReduce]=useState(false);
 const latest=useRef({slowMotion,reducedMotion,onChange,onChangeEnd,onStatus,systemReduce});latest.current={slowMotion,reducedMotion,onChange,onChangeEnd,onStatus,systemReduce};const last=useRef(''),lastStatus=useRef('');
 useEffect(()=>{let live=true;AccessibilityInfo.isReduceMotionEnabled().then(v=>live&&setSystemReduce(v));const sub=AccessibilityInfo.addEventListener('reduceMotionChanged',setSystemReduce);return()=>{live=false;sub.remove();};},[]);
 useEffect(()=>{let active=true,raf=0,prev=Date.now();const frame=()=>{if(!active)return;const now=Date.now(),s=model.current,f=latest.current;tick(s,(now-prev)/1000,f.slowMotion,f.reducedMotion??f.systemReduce);prev=now;const v=pathValue(s.anchors);if(v.svg!==last.current){last.current=v.svg;f.onChange?.(v);}const status={selected:s.selected,count:s.anchors.length,mode:s.anchors[s.selected].mode,playing:s.playing,zoom:s.zoom,length:v.length},key=JSON.stringify(status);if(key!==lastStatus.current){lastStatus.current=key;f.onStatus?.(status);}setScene(pathScene(s));raf=requestAnimationFrame(frame);};raf=requestAnimationFrame(frame);return()=>{active=false;cancelAnimationFrame(raf);g.cancel();};},[g]);
 const end=()=>latest.current.onChangeEnd?.(pathValue(model.current.anchors));
 const pan=useMemo(()=>PanResponder.create({onStartShouldSetPanResponder:()=>true,onMoveShouldSetPanResponder:()=>true,onPanResponderTerminationRequest:()=>false,onPanResponderGrant:e=>g.down({x:e.nativeEvent.locationX,y:e.nativeEvent.locationY}),onPanResponderMove:e=>g.move({x:e.nativeEvent.locationX,y:e.nativeEvent.locationY}),onPanResponderRelease:()=>{g.up();end();},onPanResponderTerminate:()=>{g.cancel();end();}}),[g]);
 useImperativeHandle(ref,()=>({split:()=>{const s=model.current;splitSegment(s,Math.min(s.selected,s.anchors.length-2));end();},mode:v=>{setMode(model.current,v);end();},undo:()=>{undo(model.current);end();},reset:()=>{Object.assign(model.current,createEditor(initialAnchors));end();},zoom:f=>zoom(model.current,f),play:()=>{model.current.playing=!model.current.playing;},select:i=>{model.current.selected=Math.max(0,Math.min(model.current.anchors.length-1,i));model.current.reveal=0;},value:()=>pathValue(model.current.anchors)}));
 return <View style={{width:340,height:320,borderRadius:10,overflow:'hidden',backgroundColor:c.bg}} {...pan.panHandlers} accessibilityLabel="Motion path canvas. Drag anchor squares or tangent circles. Drag empty space to pan. Use the point and mode buttons for alternatives."><Canvas pointerEvents="none" style={{width:340,height:320}}><Rect x={0} y={0} width={340} height={320} color={c.bg}/>{scene.grid.map((l,i)=><Line key={i} p1={l.a} p2={l.b} strokeWidth={.5} color={c.grid}/>)}<Path path={scene.path} color={c.curve} style="stroke" strokeWidth={2.2} strokeCap="round"/><Path path={scene.trail} color={c.ink} style="stroke" strokeWidth={3.2} strokeCap="round"/>{scene.handles.map((h,i)=><React.Fragment key={i}><Line p1={h.end} p2={h.p} color={c.muted} strokeWidth={1}/><Circle cx={h.p.x} cy={h.p.y} r={4.5} color={c.bg}/><Circle cx={h.p.x} cy={h.p.y} r={4.5} color={c.accent} style="stroke" strokeWidth={1.5}/></React.Fragment>)}{scene.anchors.map((a,i)=><React.Fragment key={i}>{a.selected&&<Circle cx={a.p.x} cy={a.p.y} r={12} color={c.curve} opacity={.12}/>}<Rect x={a.p.x-4.5} y={a.p.y-4.5} width={9} height={9} color={a.selected?c.curve:c.bg}/><Rect x={a.p.x-4.5} y={a.p.y-4.5} width={9} height={9} color={c.curve} style="stroke" strokeWidth={1.5}/></React.Fragment>)}<Circle cx={scene.marker.x} cy={scene.marker.y} r={10} color={c.ink} opacity={.09}/><Circle cx={scene.marker.x} cy={scene.marker.y} r={5} color={c.ink}/></Canvas></View>;
});

export type Point={x:number;y:number};
export type Anchor={p:Point;incoming:Point;outgoing:Point;mode:'smooth'|'corner'};
export type PathValue={anchors:Anchor[];svg:string;length:number};
export type Editor={anchors:Anchor[];selected:number;distance:number;playing:boolean;zoom:number;pan:Point;reveal:number;history:Anchor[][]};
export const W=340,H=320;
export const add=(a:Point,b:Point):Point=>({x:a.x+b.x,y:a.y+b.y});
export const sub=(a:Point,b:Point):Point=>({x:a.x-b.x,y:a.y-b.y});
export const mul=(a:Point,n:number):Point=>({x:a.x*n,y:a.y*n});
export const length=(a:Point)=>Math.hypot(a.x,a.y);
export const mix=(a:Point,b:Point,t:number)=>add(mul(a,1-t),mul(b,t));
export const clone=(a:Anchor[]):Anchor[]=>a.map(n=>({p:{...n.p},incoming:{...n.incoming},outgoing:{...n.outgoing},mode:n.mode}));
export function initialAnchors():Anchor[]{return [
 {p:{x:40,y:220},incoming:{x:0,y:0},outgoing:{x:58,y:0},mode:'corner'},
 {p:{x:174,y:94},incoming:{x:-48,y:0},outgoing:{x:48,y:0},mode:'smooth'},
 {p:{x:300,y:205},incoming:{x:-52,y:0},outgoing:{x:0,y:0},mode:'corner'}];}
export function createEditor(anchors=initialAnchors()):Editor{if(anchors.length<2||anchors.length>12||anchors.some(a=>![a.p,a.incoming,a.outgoing].every(p=>Number.isFinite(p.x)&&Number.isFinite(p.y))))throw new Error('Motion path requires 2–12 finite anchors');return {anchors:clone(anchors),selected:1,distance:0,playing:true,zoom:1,pan:{x:0,y:0},reveal:0,history:[]};}
export function control(a:Anchor[],i:number):Point[]{return [a[i].p,add(a[i].p,a[i].outgoing),add(a[i+1].p,a[i+1].incoming),a[i+1].p];}
export function cubic(q:Point[],t:number):Point{const s=1-t;return {x:s*s*s*q[0].x+3*s*s*t*q[1].x+3*s*t*t*q[2].x+t*t*t*q[3].x,y:s*s*s*q[0].y+3*s*s*t*q[1].y+3*s*t*t*q[2].y+t*t*t*q[3].y};}
export function tangent(q:Point[],t:number):Point{const s=1-t;return add(add(mul(sub(q[1],q[0]),3*s*s),mul(sub(q[2],q[1]),6*s*t)),mul(sub(q[3],q[2]),3*t*t));}
export type Arc={segment:number;t:number;distance:number;p:Point};
/** Dense chord integration; positions are inverted by distance, not Bezier parameter. */
export function arcTable(anchors:Anchor[],steps=120):Arc[]{const table:Arc[]=[{segment:0,t:0,distance:0,p:anchors[0].p}];let distance=0,last=anchors[0].p;for(let i=0;i<anchors.length-1;i++){const q=control(anchors,i);for(let j=1;j<=steps;j++){const t=j/steps,p=cubic(q,t);distance+=length(sub(p,last));table.push({segment:i,t,distance,p});last=p;}}return table;}
export function atDistance(table:Arc[],distance:number){const total=table[table.length-1].distance,d=total>0?Math.max(0,Math.min(total,distance)):0;let lo=0,hi=table.length-1;while(hi-lo>1){const mid=(lo+hi)>>1;if(table[mid].distance<d)lo=mid;else hi=mid;}const a=table[lo],b=table[hi],f=(d-a.distance)/(b.distance-a.distance||1);const segment=b.segment,t=a.segment===b.segment?a.t+(b.t-a.t)*f:b.t*f;return {p:mix(a.p,b.p,f),segment,t};}
const fmt=(n:number)=>Number(n.toFixed(3)).toString();
export function svgPath(a:Anchor[]){let s=`M ${fmt(a[0].p.x)} ${fmt(a[0].p.y)}`;for(let i=0;i<a.length-1;i++){const q=control(a,i);s+=` C ${q.slice(1).map(p=>`${fmt(p.x)} ${fmt(p.y)}`).join(' ')}`;}return s;}
export function pathValue(a:Anchor[]):PathValue{const t=arcTable(a);return {anchors:clone(a),svg:svgPath(a),length:t[t.length-1].distance};}
export function remember(s:Editor){s.history.push(clone(s.anchors));if(s.history.length>30)s.history.shift();}
export function undo(s:Editor){const a=s.history.pop();if(a){s.anchors=a;s.selected=Math.min(s.selected,a.length-1);s.reveal=0;}}
/** Exact de Casteljau split. Endpoint modes become corner if necessary to preserve the original curve. */
export function splitSegment(s:Editor,i:number,t=.5){if(s.anchors.length>=12||i<0||i>=s.anchors.length-1||t<=0||t>=1)return false;remember(s);const q=control(s.anchors,i),a=mix(q[0],q[1],t),b=mix(q[1],q[2],t),c=mix(q[2],q[3],t),d=mix(a,b,t),e=mix(b,c,t),p=mix(d,e,t);s.anchors[i].outgoing=sub(a,q[0]);s.anchors[i+1].incoming=sub(c,q[3]);s.anchors.splice(i+1,0,{p,incoming:sub(d,p),outgoing:sub(e,p),mode:'smooth'});s.selected=i+1;s.reveal=0;return true;}
export function setMode(s:Editor,mode:'smooth'|'corner'){const a=s.anchors[s.selected];if(a.mode===mode)return;remember(s);a.mode=mode;if(mode==='smooth'){let dir=length(a.outgoing)>1e-6?a.outgoing:mul(a.incoming,-1);if(length(dir)<1e-6)dir={x:36,y:0};const u=mul(dir,1/length(dir));a.outgoing=mul(u,length(a.outgoing)||36);a.incoming=mul(u,-(length(a.incoming)||36));}}
export function moveHandle(a:Anchor,key:'incoming'|'outgoing',p:Point){a[key]=sub(p,a.p);if(a.mode==='smooth'){const other=key==='incoming'?'outgoing':'incoming',n=length(a[key]);if(n>1e-6)a[other]=mul(a[key],-length(a[other])/n);}}
export function screen(s:Editor,p:Point):Point{return {x:(p.x-W/2)*s.zoom+W/2+s.pan.x,y:(p.y-H/2)*s.zoom+H/2+s.pan.y};}
export function world(s:Editor,p:Point):Point{return {x:(p.x-W/2-s.pan.x)/s.zoom+W/2,y:(p.y-H/2-s.pan.y)/s.zoom+H/2};}
export function zoom(s:Editor,factor:number){s.zoom=Math.max(.75,Math.min(2,s.zoom*factor));}
export function tick(s:Editor,dt:number,slow=false,reduce=false){s.reveal=reduce?1:1-(1-s.reveal)*Math.exp(-Math.min(dt,.05)*12*(slow?.25:1));if(s.playing&&!reduce)s.distance+=48*Math.min(dt,.05)*(slow?.25:1);}
export type Hit={kind:'anchor'|'incoming'|'outgoing';index:number};
export function hit(s:Editor,p:Point):Hit|null{const a=s.anchors[s.selected];for(const key of ['incoming','outgoing'] as const){if((key==='incoming'&&s.selected===0)||(key==='outgoing'&&s.selected===s.anchors.length-1))continue;if(length(sub(p,screen(s,add(a.p,a[key]))))<17)return {kind:key,index:s.selected};}for(let i=s.anchors.length-1;i>=0;i--)if(length(sub(p,screen(s,s.anchors[i].p)))<19)return {kind:'anchor',index:i};return null;}
export function gesture(s:Editor){let active:Hit|null=null,origin:Point|null=null,pan={x:0,y:0},snapshot:Anchor[]|null=null,moved=false;return {
 down(p:Point){active=hit(s,p);origin=p;pan={...s.pan};moved=false;snapshot=clone(s.anchors);if(active){if(s.selected!==active.index)s.reveal=0;s.selected=active.index;}},
 move(p:Point){if(!origin)return;if(!moved&&length(sub(p,origin))<2)return;if(!moved&&active)remember(s);moved=true;if(!active){s.pan=add(pan,sub(p,origin));return;}const a=s.anchors[active.index],q=world(s,p);if(active.kind==='anchor')a.p=q;else moveHandle(a,active.kind,q);},
 up(){origin=null;active=null;snapshot=null;},
 cancel(){if(snapshot){s.anchors=snapshot;if(moved&&active)s.history.pop();s.pan=pan;}origin=null;active=null;snapshot=null;},
};}

import {add,arcTable,atDistance,control,cubic,screen,tangent,type Editor,type Point} from './pathMath';
export const palette={bg:'#15191a',grid:'#2b3132',ink:'#eef2e9',muted:'#8e9a94',curve:'#b5d49a',accent:'#ecad78'};
export type Scene={grid:{a:Point;b:Point}[];path:string;trail:string;handles:{p:Point;end:Point;kind:'incoming'|'outgoing'}[];anchors:{p:Point;selected:boolean;corner:boolean}[];marker:Point;angle:number;length:number;progress:number};
export function pathScene(s:Editor):Scene{const table=arcTable(s.anchors),total=table[table.length-1].distance,cycle=s.distance%Math.max(total*2,1),travel=cycle<=total?cycle:total*2-cycle,where=atDistance(table,travel),v=tangent(control(s.anchors,where.segment),where.t),grid:Scene['grid']=[];for(let x=0;x<=340;x+=20){const a=screen(s,{x,y:-500}),b=screen(s,{x,y:800});grid.push({a,b});}for(let y=0;y<=320;y+=20)grid.push({a:screen(s,{x:-500,y}),b:screen(s,{x:800,y})});const point=(p:Point)=>`${p.x.toFixed(3)} ${p.y.toFixed(3)}`;let path=`M ${point(screen(s,s.anchors[0].p))}`;for(let i=0;i<s.anchors.length-1;i++)path+=` C ${control(s.anchors,i).slice(1).map(p=>point(screen(s,p))).join(' ')}`;let trail='';for(let j=0;j<=22;j++){const p=screen(s,atDistance(table,Math.max(0,travel-32+j*32/22)).p);trail+=`${j?' L':'M'} ${point(p)}`;}const a=s.anchors[s.selected],handles:Scene['handles']=[];if(s.selected>0)handles.push({p:screen(s,add(a.p,{x:a.incoming.x*s.reveal,y:a.incoming.y*s.reveal})),end:screen(s,a.p),kind:'incoming'});if(s.selected<s.anchors.length-1)handles.push({p:screen(s,add(a.p,{x:a.outgoing.x*s.reveal,y:a.outgoing.y*s.reveal})),end:screen(s,a.p),kind:'outgoing'});return {grid,path,trail,handles,anchors:s.anchors.map((a,i)=>({p:screen(s,a.p),selected:i===s.selected,corner:a.mode==='corner'})),marker:screen(s,where.p),angle:Math.atan2(v.y,v.x),length:total,progress:total?travel/total:0};}

import React,{useRef,useState} from 'react';import {Pressable,Text,View} from 'react-native';
import {MotionPathEditor,type MotionPathHandle} from './MotionPathEditor';
export default function Example(){const ref=useRef<MotionPathHandle>(null),[slow,setSlow]=useState(false),[status,setStatus]=useState({selected:1,count:3,mode:'smooth',playing:true,zoom:1,length:0}),[svg,setSvg]=useState('');const button=(label:string,action:()=>void,active=false)=><Pressable key={label} accessibilityRole="button" accessibilityLabel={label} accessibilityState={{selected:active}} onPress={action} style={{minHeight:40,minWidth:40,paddingHorizontal:10,alignItems:'center',justifyContent:'center',borderRadius:7,borderWidth:1,borderColor:'#ccd3c6',backgroundColor:active?'#252c26':'#f8faf5'}}><Text style={{fontFamily:'Geist',fontSize:12,color:active?'#fff':'#30372e'}}>{label}</Text></Pressable>;
return <View style={{alignItems:'center',gap:13}}><MotionPathEditor ref={ref} slowMotion={slow} onStatus={setStatus} onChange={v=>setSvg(v.svg)}/><Text style={{fontFamily:'Geist',fontSize:12,color:'#4d594e',fontVariant:['tabular-nums']}}>{status.count} anchors · {Math.round(status.length)} units · {status.zoom.toFixed(1)}×</Text><View style={{flexDirection:'row',gap:5,flexWrap:'wrap',justifyContent:'center',maxWidth:340}}>{Array.from({length:status.count},(_,i)=>button(`Point ${i+1}`,()=>ref.current?.select(i),i===status.selected))}</View><View style={{flexDirection:'row',gap:5,flexWrap:'wrap',justifyContent:'center',maxWidth:340}}>{button(status.playing?'Pause':'Play',()=>ref.current?.play())}{button('Split',()=>ref.current?.split())}{button('Smooth',()=>ref.current?.mode('smooth'),status.mode==='smooth')}{button('Corner',()=>ref.current?.mode('corner'),status.mode==='corner')}{button('Undo',()=>ref.current?.undo())}{button('−',()=>ref.current?.zoom(.8))}{button('+',()=>ref.current?.zoom(1.25))}{button('Reset',()=>ref.current?.reset())}{button('Slow motion',()=>setSlow(v=>!v),slow)}</View><Text numberOfLines={3} accessibilityLabel={`Path output ${svg}`} style={{fontFamily:'Geist',fontSize:10,lineHeight:16,color:'#63705f',width:340}}>{svg}</Text></View>;}
